import assert from "node:assert/strict";
import test from "node:test";
import { initialize, MetaModel } from "../dist/node.js";

test("variable creation rejects JavaScript coercion without changing the model", async () => {
    await initialize();
    const model = new MetaModel("invalid-variable-input");
    const x = model.addVariable("x", { lowerBound: 0, upperBound: 10 });
    const token = x.token();
    model.setSolution(new Float64Array([4]));
    const before = model.toLinearTriadModel();
    for (const options of [
        null, [], { lowerBound: "2" }, { lowerBound: null }, { upperBound: NaN },
        { type: null }, { type: 1 }, { type: "unknown" }, { type: "integer", upperBound: 0.5 },
    ]) {
        assert.throws(() => model.addVariable("invalid", options), { code: "InvalidInput" });
        assert.deepEqual(model.toLinearTriadModel(), before);
        assert.equal(token.result(), 4);
    }
    assert.equal(model.addVariable("unbounded", { lowerBound: -Infinity, upperBound: Infinity }).index, 1);
    token.dispose(); model.dispose();
});

test("names are validated in JS so caller mistakes never surface as solver failures", async () => {
    await initialize();
    const model = new MetaModel("names");
    const before = model.toLinearTriadModel();
    // 把非字符串交给 WASM 会变成 wasm trap，只能报 ExecutionFailure——必须在 JS 边界拦成 InvalidInput。
    // A non-string reaches WASM as a trap and can only report ExecutionFailure, so it must be caught as InvalidInput
    // at the JS boundary.
    for (const name of [{}, [], "", null, undefined, 7, true]) {
        assert.throws(() => model.addVariable(name), { code: "InvalidInput" }, `addVariable ${JSON.stringify(name)}`);
        assert.throws(() => model.addLinearSymbol(name, { terms: [] }), { code: "InvalidInput" }, `addLinearSymbol ${JSON.stringify(name)}`);
        // 拒绝后模型必须完全没有变化。 / The model must be untouched after a rejection.
        assert.deepEqual(model.toLinearTriadModel(), before);
    }
    // 合法名称照常工作；本测试只钉子边界校验，不假设重名规则。
    // A valid name still works; this test only pins boundary validation and makes no claim about duplicate names.
    assert.equal(model.addVariable("x", { lowerBound: 0, upperBound: 5 }).index, 0);
    assert.equal(model.addVariable("y").index, 1);
    model.dispose();
});

test("Rust linear algebra preserves operands, combines terms and evaluates in variable order", async () => {
    await initialize();
    const model = new MetaModel("algebra");
    const x = model.addVariable("x");
    const y = model.addVariable("y");
    const a = model.linearExpression([[y, 4], [x, 2], [x, 3]], 7);
    const b = model.linearExpression([[x, 1], [y, -4]], -2);
    const sum = a.add(b);
    const difference = a.sub(b);
    const scaled = sum.mul(2);
    const offset = scaled.add(3);
    const shifted = offset.sub(5);
    const negative = shifted.neg();
    assert.deepEqual([...a.coefficients()], [5, 4]);
    assert.equal(a.constant(), 7);
    assert.equal(a.evaluate(new Float64Array([2, 3])), 29);
    assert.deepEqual([...sum.coefficients()], [6, 0]);
    assert.equal(sum.constant(), 5);
    assert.deepEqual([...difference.coefficients()], [4, 8]);
    assert.equal(negative.evaluate(new Float64Array([2, 3])), -32);
    const copy = a.coefficients();
    copy[0] = 99;
    assert.equal(a.coefficients()[0], 5);
    for (const value of [a, b, sum, difference, scaled, offset, shifted, negative]) value.dispose();
    model.dispose();
});

test("object constraints normalize constants and match the existing dense model exactly", async () => {
    await initialize();
    const model = new MetaModel("equivalent");
    const x = model.addVariable("x", { lowerBound: 0, upperBound: 10 });
    const y = model.addVariable("y", { type: "binary" });
    const lhs = model.linearExpression([[x, 1], [y, 1]], 3);
    const rhs = model.linearExpression([], 7);
    const inequality = lhs.le(rhs);
    const objective = model.linearExpression([[x, 2], [y, 1]]);
    model.setLinearObjective(objective, "maximize");
    model.addInequality(inequality, "capacity");
    for (const value of [lhs, rhs, inequality, objective]) value.dispose();
    const dense = new MetaModel("equivalent");
    const dx = dense.addVariable("x", { lowerBound: 0, upperBound: 10 });
    const dy = dense.addVariable("y", { type: "binary" });
    dense.setLinearObjective([[dx, 2], [dy, 1]], "maximize");
    dense.addLinearConstraint({ name: "capacity", terms: [[dx, 1], [dy, 1]], relation: "le", rhs: 4 });
    assert.deepEqual(model.toLinearTriadModel(), dense.toLinearTriadModel());
    const unchanged = model.toLinearTriadModel();
    const constantObjective = model.linearExpression([[x, 1]], 1);
    assert.throws(() => model.setLinearObjective(constantObjective), { code: "Unsupported" });
    assert.deepEqual(model.toLinearTriadModel(), unchanged);
    constantObjective.dispose();
    model.dispose(); dense.dispose();
});

test("expression ownership and lifetimes are checked at Rust and SDK boundaries", async () => {
    await initialize();
    const model = new MetaModel("owner");
    const x = model.addVariable("x");
    const value = x.toLinear();
    const relation = value.ge(0);
    const other = new MetaModel("other");
    const foreign = other.linearExpression([], 1);
    assert.throws(() => value.add(foreign), { code: "InvalidReference" });
    assert.throws(() => value.le(foreign), { code: "InvalidReference" });
    assert.throws(() => other.setLinearObjective(value), { code: "InvalidReference" });
    assert.throws(() => other.addInequality(relation, "foreign"), { code: "InvalidReference" });
    const copiedRelation = value.eq(0);
    value.dispose(); value.dispose();
    assert.throws(() => value.constant(), { code: "Disposed" });
    model.addInequality(copiedRelation, "snapshot");
    copiedRelation.dispose();
    assert.throws(() => model.addInequality(copiedRelation, "freed"), { code: "Disposed" });
    const live = x.toLinear();
    model.addVariable("later");
    assert.deepEqual([...live.coefficients()], [1, 0]);
    assert.throws(() => live.evaluate(new Float64Array([1])), { code: "InvalidInput" });
    model.dispose();
    assert.throws(() => live.evaluate(new Float64Array([1, 2])), { code: "Disposed" });
    assert.throws(() => live.add(1), { code: "Disposed" });
    assert.throws(() => x.toLinear(), { code: "Disposed" });
    live.dispose(); relation.dispose(); foreign.dispose(); other.dispose();
});

test("invalid expression values and normalization overflow fail before model mutation", async () => {
    await initialize();
    const model = new MetaModel("invalid");
    const x = model.addVariable("x");
    const value = x.toLinear();
    const large = model.linearExpression([[x, Number.MAX_VALUE]], -Number.MAX_VALUE);
    assert.throws(() => model.linearExpression([[x, NaN]]), { code: "InvalidInput" });
    assert.throws(() => model.linearExpression([[x, null]]), { code: "InvalidInput" });
    assert.throws(() => model.linearExpression([[x, "2"]]), { code: "InvalidInput" });
    assert.throws(() => model.linearExpression([[x, Number.MAX_VALUE], [x, Number.MAX_VALUE]]), { code: "InvalidInput" });
    assert.throws(() => model.linearExpression([], Infinity), { code: "InvalidInput" });
    assert.throws(() => large.mul(2), { code: "InvalidInput" });
    assert.throws(() => large.le(Number.MAX_VALUE), { code: "InvalidInput" });
    assert.throws(() => value.add(NaN), { code: "InvalidInput" });
    assert.throws(() => value.mul(Infinity), { code: "InvalidInput" });
    assert.throws(() => value.evaluate(new Float64Array([Infinity])), { code: "InvalidInput" });
    const doubled = value.mul(2);
    assert.throws(() => doubled.evaluate(new Float64Array([Number.MAX_VALUE])), { code: "InvalidInput" });
    for (const item of [value, large, doubled]) item.dispose();
    model.dispose();
});

test("IIS report reader validates self-consistency and never treats text as a conclusion", async () => {
    await initialize();
    const { LinearIisReport } = await import("../dist/core.js");
    const report = ids => ({ algorithm: "elastic", constraintIds: ids, lowerBoundVariables: [], upperBoundVariables: [],
        originalConstraintCount: 2, originalVariableCount: 1 });
    // 原生端真实算出的形状必须可读，且身份保持原顺序与原文。
    // The shape a native host really produces must read back with identities kept in order and verbatim.
    const text = JSON.stringify(report(["linear-constraint:8#m:1#0:13#at_least_five:0#", "linear-constraint:8#m:1#1:11#at_most_one:0#"]));
    const parsed = LinearIisReport.fromJson(text);
    assert.equal(parsed.algorithm(), "elastic");
    assert.equal(parsed.constraintIds().length, 2);
    assert.ok(parsed.constraintIds()[0].endsWith("13#at_least_five:0#"));
    assert.deepEqual(parsed.lowerBoundVariables(), []);
    assert.equal(parsed.originalConstraintCount(), 2);
    assert.equal(parsed.originalVariableCount(), 1);
    assert.equal(parsed.toJson(), text);
    parsed.dispose();
    assert.throws(() => parsed.toJson(), { code: "Disposed" });
    // 子系统大于原模型、空身份、重复身份、非文本输入都必须拒绝。
    // A subsystem larger than its model, empty identities, repeated identities and non-text input must all fail.
    for (const invalid of [
        { ...report(["a", "b", "c"]) },
        { ...report(["a", ""]) },
        { ...report(["a", "a"]) },
        { ...report(["a"]), originalVariableCount: 0, lowerBoundVariables: ["x"] },
        { ...report(["a"]), algorithm: "unknown" },
    ]) assert.throws(() => LinearIisReport.fromJson(JSON.stringify(invalid)), { code: "InvalidInput" }, JSON.stringify(invalid));
    for (const invalid of ["", "not json", "{}"]) assert.throws(() => LinearIisReport.fromJson(invalid), { code: "InvalidInput" });
    assert.throws(() => LinearIisReport.fromJson(7), { code: "InvalidInput" });
});

test("solution pool reader validates self-consistency without certifying optimality", async () => {
    await initialize();
    const { LinearSolutionPoolReport } = await import("../dist/core.js");
    const text = JSON.stringify({ modelFingerprint: "a".repeat(64), variableIds: ["x", "y"],
        solutions: [[2, 2], [3, 1], [0, 0]], bestObjective: 4 });
    const parsed = LinearSolutionPoolReport.fromJson(text);
    assert.equal(parsed.modelFingerprint(), "a".repeat(64));
    assert.deepEqual(parsed.variableIds(), ["x", "y"]);
    assert.equal(parsed.count(), 3);
    // 每个解都是完整向量；解池可以含次优解，reader 只如实返回。
    // Every solution is a complete vector; a pool may hold suboptimal members and the reader returns them verbatim.
    assert.deepEqual([...parsed.solution(0)], [2, 2]);
    assert.deepEqual([...parsed.solution(2)], [0, 0]);
    assert.equal(parsed.bestObjective(), 4);
    // `toJson()` 是 Rust 归一化后的文本（f64 写成 2.0），因此比对语义而不是字节。
    // `toJson()` is Rust-normalized text (f64 becomes 2.0), so compare semantics rather than bytes.
    assert.deepEqual(JSON.parse(parsed.toJson()), JSON.parse(text));
    assert.throws(() => parsed.solution(3), { code: "InvalidInput" });
    parsed.dispose();
    assert.throws(() => parsed.toJson(), { code: "Disposed" });
    // 向量长度不符、非有限值、身份重复/为空、少于两个解、缺指纹都必须拒绝。
    // Mismatched vector length, non-finite values, repeated or empty identities, a single solution and a missing
    // fingerprint must all fail.
    const variant = changes => JSON.stringify({ modelFingerprint: "a".repeat(64), variableIds: ["x", "y"], solutions: [[2, 2], [3, 1]], bestObjective: 4, ...changes });
    for (const invalid of [
        variant({ solutions: [[2, 2], [3]] }), variant({ solutions: [[2, 2], [3, Number.NaN]] }),
        variant({ variableIds: ["x", "x"] }), variant({ variableIds: ["x", ""] }),
        variant({ solutions: [[2, 2]] }), variant({ modelFingerprint: "" }), variant({ variableIds: [] }),
    ]) assert.throws(() => LinearSolutionPoolReport.fromJson(invalid), { code: "InvalidInput" }, invalid);
    // 非有限目标值只能用原始文本构造：`JSON.stringify` 会把 Infinity/NaN 变成 null。
    // A non-finite objective can only be built from raw text, since `JSON.stringify` turns Infinity/NaN into null.
    const raw = suffix => `{"modelFingerprint":"${"a".repeat(64)}","variableIds":["x"],"solutions":[[1],[2]],${suffix}}`;
    assert.throws(() => LinearSolutionPoolReport.fromJson(raw('"bestObjective":1e999')), { code: "InvalidInput" });
    assert.throws(() => LinearSolutionPoolReport.fromJson("{}"), { code: "InvalidInput" });
    assert.throws(() => LinearSolutionPoolReport.fromJson(7), { code: "InvalidInput" });
});

test("sensitivity reader validates the report in Rust and rejects inconsistent text", async () => {
    await initialize();
    const { LocalConstraintSensitivityReport } = await import("../dist/core.js");
    // 形状取自原 core 报告：版本、baseline、固定整数数、每条原始约束的局部证据。
    // The shape mirrors the original core report: version, baseline, fixed-integer count and per-constraint evidence.
    // 枚举名由原 core 的 SCREAMING_SNAKE_CASE 重命名给出，不是普通 camelCase。
    // Enum names come from the original core's SCREAMING_SNAKE_CASE renaming, not ordinary camelCase.
    const report = changes => ({ schemaVersion: "1.0", scope: "FIXED_INTEGER_INCUMBENT", baselineObjective: 4, lpObjective: 4, fixedIntegerCount: 2,
        constraints: [{ constraintId: "capacity", dualValue: 1, localEffective: true, status: "REACHABLE", scope: "FIXED_INTEGER_INCUMBENT", activity: null }], status: "REACHABLE", terminationReason: null, unavailableReason: null, ...changes });
    const parsed = LocalConstraintSensitivityReport.fromJson(JSON.stringify(report()));
    assert.equal(parsed.schemaVersion(), "1.0");
    assert.equal(parsed.baselineObjective(), 4);
    assert.equal(parsed.fixedIntegerCount(), 2);
    assert.deepEqual(parsed.constraintIds(), ["capacity"]);
    assert.deepEqual(JSON.parse(parsed.toJson()), report());
    parsed.dispose();
    assert.throws(() => parsed.toJson(), { code: "Disposed" });
    // 空版本、非有限 baseline、空约束身份、非有限对偶都必须由原 core 的 validate 拒绝。
    // An empty version, non-finite baseline, empty constraint identity and non-finite dual must all be rejected by the
    // original core `validate`.
    for (const invalid of [report({ schemaVersion: "" }), report({ constraints: [{ constraintId: "", dualValue: 1, localEffective: true, status: "REACHABLE", scope: "FIXED_INTEGER_INCUMBENT", activity: null }] })]) {
        assert.throws(() => LocalConstraintSensitivityReport.fromJson(JSON.stringify(invalid)), { code: "InvalidInput" }, JSON.stringify(invalid));
    }
    // 非有限 baseline 同样只能用原始文本构造：`JSON.stringify` 会把 Infinity 写成 null（那是缺字段，不是非有限值）。
    // A non-finite baseline can also only be built from raw text: `JSON.stringify` writes Infinity as null, which is a
    // missing field rather than a non-finite value.
    assert.throws(() => LocalConstraintSensitivityReport.fromJson(JSON.stringify(report({ baselineObjective: 4 })).replace('"baselineObjective":4', '"baselineObjective":1e999')), { code: "InvalidInput" });
    assert.throws(() => LocalConstraintSensitivityReport.fromJson("not json"), { code: "InvalidInput" });
    assert.throws(() => LocalConstraintSensitivityReport.fromJson(7), { code: "InvalidInput" });
});

test("certified pricing duals reject every report that is not an optimal LP certificate", async () => {
    await initialize();
    const { MetaModel, CertifiedPricingDuals } = await import("../dist/core.js");
    const model = new MetaModel("pricing-negative");
    const x = model.addVariable("x", { lowerBound: 0, upperBound: 10 });
    model.addLinearConstraint({ name: "capacity", terms: [[x, 1]], relation: "le", rhs: 2 });
    model.setLinearObjective([[x, 1]], "maximize");
    const artifact = model.toLinearTriadModel();
    model.dispose();
    // 非报告文本、缺字段、伪造对偶都必须拒绝；本类不补 0 也不猜。
    // Non-report text, missing fields and fabricated duals must all fail; the class never fills in zeroes or guesses.
    for (const report of ["", "not json", "{}", JSON.stringify({ schemaVersion: "1.0" }),
        JSON.stringify({ schemaVersion: "1.0", status: "FEASIBLE", terminationReason: "COMPLETED",
            solution: { values: [2], objective: 2, objectiveValue: 2, dualSolution: [1] } })]) {
        assert.throws(() => CertifiedPricingDuals.verify(artifact, report), { code: "InvalidInput" }, report.slice(0, 60));
    }
    assert.throws(() => CertifiedPricingDuals.verify(artifact, 7), { code: "InvalidInput" });
    assert.throws(() => CertifiedPricingDuals.verify(null, "{}"), { code: "InvalidInput" });
});

test("certified pricing duals come from a real optimal LP report", { skip: !process.env.OSPF_E2E_URL }, async () => {
    await initialize();
    const { MetaModel, CertifiedPricingDuals } = await import("../dist/core.js");
    const { HttpClient } = await import("../dist/framework.js");
    const client = new HttpClient({ baseUrl: process.env.OSPF_E2E_URL, token: process.env.OSPF_TOKEN });
    const model = new MetaModel("pricing-e2e");
    const x = model.addVariable("x", { lowerBound: 0, upperBound: 10 });
    model.addLinearConstraint({ name: "capacity", terms: [[x, 1]], relation: "le", rhs: 2 });
    model.setLinearObjective([[x, 1]], "maximize");
    const artifact = model.toLinearTriadModel();
    model.dispose();
    const submitted = await client.submit({ protocolVersion: 1, solver: "scip", model: artifact, timeLimitMs: 30_000 });
    let view = submitted;
    for (let attempt = 0; view.status === "running" && attempt < 2_000; attempt++) {
        await new Promise(resolve => setTimeout(resolve, 25));
        view = await client.get(submitted.id);
    }
    assert.equal(view.status, "completed", JSON.stringify(view.error));
    const certified = CertifiedPricingDuals.verify(artifact, view.reportJson);
    // 对偶按稳定约束身份给出，且绑定到被认证的模型指纹。
    // Duals are keyed by stable constraint identity and bound to the certified model fingerprint.
    assert.equal(certified.modelFingerprint(), artifact.fingerprint);
    assert.equal(certified.constraintIds().length, certified.duals().length);
    assert.equal(certified.duals().length, 1);
    assert.ok(certified.constraintIds()[0].endsWith("capacity:0#"), certified.constraintIds()[0]);
    assert.equal(certified.dual(certified.constraintIds()[0]), 1);
    assert.throws(() => certified.dual("ghost"), { code: "InvalidInput" });
    // 旧报告配新模型必须失败。 / An old report paired with a new model must fail.
    const other = new MetaModel("pricing-e2e-other");
    const y = other.addVariable("x", { lowerBound: 0, upperBound: 10 });
    other.addLinearConstraint({ name: "capacity", terms: [[y, 1]], relation: "le", rhs: 3 });
    other.setLinearObjective([[y, 1]], "maximize");
    const foreign = other.toLinearTriadModel();
    other.dispose();
    assert.throws(() => CertifiedPricingDuals.verify(foreign, view.reportJson), { code: "InvalidInput" });
    certified.dispose();
    assert.throws(() => certified.toJson(), { code: "Disposed" });
    await client.release(submitted.id);
});

test("sweep report reader enforces exactly one verdict per case", async () => {
    await initialize();
    const { LinearSweepReport } = await import("../dist/core.js");
    const summary = { problemStatus: "feasible", terminationReason: "completed", objectiveValue: 4, values: [2, 2],
        hasOptimalityProof: true, relativeGap: null, absoluteGap: null, nodes: null, solveTimeMs: 1 };
    const report = changes => ({ modelFingerprint: "f".repeat(64),
        cases: [{ caseId: "a", summary }, { caseId: "b", errorCode: "ExecutionFailure", errorMessage: "boom" }], ...changes });
    const parsed = LinearSweepReport.fromJson(JSON.stringify(report()));
    assert.equal(parsed.modelFingerprint(), "f".repeat(64));
    assert.equal(parsed.count(), 2);
    assert.deepEqual(parsed.caseIds(), ["a", "b"]);
    assert.equal(parsed.hasSummary("a"), true);
    assert.equal(parsed.objectiveValue("a"), 4);
    assert.equal(parsed.hasOptimalityProof("a"), true);
    assert.equal(parsed.errorCode("a"), undefined);
    assert.equal(parsed.hasSummary("b"), false);
    assert.equal(parsed.errorCode("b"), "ExecutionFailure");
    assert.throws(() => parsed.hasSummary("ghost"), { code: "InvalidInput" });
    assert.throws(() => parsed.hasSummary(""), { code: "InvalidInput" });
    parsed.dispose();
    assert.throws(() => parsed.toJson(), { code: "Disposed" });
    // 两个结论、没有结论、重复 case ID、空指纹都必须由 Rust 侧拒绝。
    // Two verdicts, no verdict, a repeated case ID and an empty fingerprint must all be rejected by Rust.
    // 这些是"报告自身不自洽"，因此错误码是 InvalidReport（不是入口参数错误）。
    // These cases mean the report is internally inconsistent, so the code is InvalidReport rather than an input error.
    for (const invalid of [
        report({ cases: [{ caseId: "a", summary, errorCode: "ExecutionFailure" }] }),
        report({ cases: [{ caseId: "a" }] }),
        report({ cases: [{ caseId: "a", summary }, { caseId: "a", summary }] }),
        report({ modelFingerprint: "" }),
    ]) assert.throws(() => LinearSweepReport.fromJson(JSON.stringify(invalid)), { code: "InvalidReport" }, JSON.stringify(invalid).slice(0, 80));
    assert.throws(() => LinearSweepReport.fromJson("not json"), { code: "InvalidInput" });
    assert.throws(() => LinearSweepReport.fromJson(7), { code: "InvalidInput" });
});

test("sweep runs one model under several cases and sorts them by case ID", { skip: !process.env.OSPF_E2E_URL }, async () => {
    await initialize();
    const { MetaModel, LinearSweepReport } = await import("../dist/core.js");
    const { HttpClient } = await import("../dist/framework.js");
    const client = new HttpClient({ baseUrl: process.env.OSPF_E2E_URL, token: process.env.OSPF_TOKEN });
    const model = new MetaModel("sweep-e2e");
    const x = model.addVariable("x", { lowerBound: 0, upperBound: 4 });
    const y = model.addVariable("y", { lowerBound: 0, upperBound: 4 });
    model.addLinearConstraint({ name: "capacity", terms: [[x, 1], [y, 1]], relation: "le", rhs: 4 });
    model.setLinearObjective([[x, 1], [y, 1]], "maximize");
    const artifact = model.toLinearTriadModel();
    model.dispose();
    // case 顺序故意打乱，结果必须按 case ID 稳定排序；未知后端只影响自己那一个 case。
    // Case order is shuffled on purpose and results must sort stably by case ID; an unknown backend only affects its
    // own case.
    const submitted = await client.submit({ protocolVersion: 1, solver: "scip", model: artifact, timeLimitMs: 60_000,
        modelKind: "linearSweep", sweepCases: [
            { caseId: "z-last", solver: "scip", timeLimitMs: 10_000 },
            { caseId: "a-first", solver: "scip", timeLimitMs: 10_000 },
            { caseId: "m-unknown", solver: "no-such-backend" },
        ] });
    let view = submitted;
    for (let attempt = 0; view.status === "running" && attempt < 4_000; attempt++) {
        await new Promise(resolve => setTimeout(resolve, 25));
        view = await client.get(submitted.id);
    }
    assert.equal(view.status, "completed", JSON.stringify(view.error));
    const report = LinearSweepReport.fromJson(view.reportJson);
    assert.equal(report.modelFingerprint(), artifact.fingerprint);
    assert.deepEqual(report.caseIds(), ["a-first", "m-unknown", "z-last"]);
    for (const caseId of ["a-first", "z-last"]) {
        assert.equal(report.hasSummary(caseId), true, caseId);
        assert.equal(report.objectiveValue(caseId), 4);
        assert.equal(report.hasOptimalityProof(caseId), true);
        assert.equal(report.errorCode(caseId), undefined);
    }
    assert.equal(report.hasSummary("m-unknown"), false);
    assert.equal(report.errorCode("m-unknown"), "ExecutionFailure");
    report.dispose();
    await client.release(submitted.id);
});

test("network flow reader keeps domain costs and never claims optimality without a solution", async () => {
    await initialize();
    const { NetworkFlowReport } = await import("../dist/core.js");
    const amount = (value, unit = "kg") => ({ value, unit });
    const summary = { problemStatus: "FEASIBLE", terminationReason: "COMPLETED", objectiveValue: 5, values: [],
        hasOptimalityProof: true, relativeGap: null, absoluteGap: null, nodes: null, solveTimeMs: 1 };
    const solution = { flows: [{ commodity: "goods", arc: "a-b", quantity: amount(5) }], spills: [], shortages: [],
        resources: [], operatingCost: amount(5), spillCost: amount(0), shortageCost: amount(0), totalCost: amount(5) };
    const parsed = NetworkFlowReport.fromJson(JSON.stringify({ summary, solution }));
    assert.equal(parsed.problemStatus(), "FEASIBLE");
    assert.equal(parsed.objectiveValue(), 5);
    assert.equal(parsed.hasOptimalityProof(), true);
    assert.equal(parsed.hasSolution(), true);
    assert.equal(parsed.totalCost(), 5);
    // 费用分项按固定顺序给出，不合并成单一总费用。
    // Cost components come in a fixed order and are never collapsed into one total.
    assert.deepEqual([...parsed.costComponents()], [5, 0, 0, 5]);
    assert.equal(parsed.flowCount(), 1);
    assert.deepEqual(parsed.flow(0), { commodity: "goods", arc: "a-b", amount: 5, unit: "kg" });
    assert.throws(() => parsed.flow(1), { code: "InvalidInput" });
    assert.deepEqual(JSON.parse(parsed.toJson()), { summary, solution });
    parsed.dispose();
    assert.throws(() => parsed.toJson(), { code: "Disposed" });
    // 声称最优却没有解，必须被 Rust 侧拒绝。
    // Claiming optimality without a solution must be rejected by Rust.
    assert.throws(() => NetworkFlowReport.fromJson(JSON.stringify({ summary })), { code: "InvalidInput" });
    // 无解报告可以读取，但解相关访问器全部报错而不是编造 0。
    // A solution-free report is readable, but every solution accessor errors instead of inventing zeroes.
    const withoutSolution = NetworkFlowReport.fromJson(JSON.stringify({ summary: { ...summary, hasOptimalityProof: false } }));
    assert.equal(withoutSolution.hasSolution(), false);
    assert.equal(withoutSolution.totalCost(), undefined);
    assert.throws(() => withoutSolution.costComponents(), { code: "InvalidInput" });
    assert.throws(() => withoutSolution.flow(0), { code: "InvalidInput" });
    withoutSolution.dispose();
    assert.throws(() => NetworkFlowReport.fromJson("not json"), { code: "InvalidInput" });
    assert.throws(() => NetworkFlowReport.fromJson(7), { code: "InvalidInput" });
});

