test("generalized flow reader keeps yield loss and node residuals apart", async () => {
    await initialize();
    const { GeneralizedFlowReport } = await import("../dist/core.js");
    const amount = (value, unit = "kg") => ({ value, unit });
    const summary = { problemStatus: "FEASIBLE", terminationReason: "COMPLETED", objectiveValue: 10, values: [],
        hasOptimalityProof: true, relativeGap: null, absoluteGap: null, nodes: null, solveTimeMs: 1 };
    const solution = { arcs: [{ id: "a-b", input: amount(10), output: amount(8), lossOrGain: amount(2), cost: amount(10) }],
        nodes: [{ id: "a", actualNetSupply: amount(10), residual: amount(0) },
                { id: "b", actualNetSupply: amount(-8), residual: amount(0) }],
        totalCost: amount(10) };
    const parsed = GeneralizedFlowReport.fromJson(JSON.stringify({ summary, solution }));
    assert.equal(parsed.objectiveValue(), 10);
    assert.equal(parsed.hasOptimalityProof(), true);
    assert.equal(parsed.totalCost(), 10);
    assert.equal(parsed.arcCount(), 1);
    // 投入/产出/产率损耗分别给出：损耗是未计产率的产出减实际产出，不是转换差额。
    // Input, output and yield loss are separate: the loss is pre-yield output minus actual output, not a conversion
    // difference.
    assert.deepEqual(parsed.arc(0), { id: "a-b", input: 10, output: 8, yieldLoss: 2, cost: 10 });
    assert.equal(parsed.nodeCount(), 2);
    assert.deepEqual(parsed.node(0), { id: "a", actualNetSupply: 10, residual: 0 });
    assert.deepEqual(parsed.node(1), { id: "b", actualNetSupply: -8, residual: 0 });
    assert.throws(() => parsed.arc(1), { code: "InvalidInput" });
    assert.throws(() => parsed.node(2), { code: "InvalidInput" });
    assert.deepEqual(JSON.parse(parsed.toJson()), { summary, solution });
    parsed.dispose();
    assert.throws(() => parsed.toJson(), { code: "Disposed" });
    assert.throws(() => GeneralizedFlowReport.fromJson(JSON.stringify({ summary })), { code: "InvalidInput" });
    const withoutSolution = GeneralizedFlowReport.fromJson(JSON.stringify({ summary: { ...summary, hasOptimalityProof: false } }));
    assert.equal(withoutSolution.hasSolution(), false);
    assert.equal(withoutSolution.totalCost(), undefined);
    assert.throws(() => withoutSolution.arc(0), { code: "InvalidInput" });
    withoutSolution.dispose();
    assert.throws(() => GeneralizedFlowReport.fromJson(7), { code: "InvalidInput" });
});

